// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.Locale;

import org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeWorkload.Corpus;
import org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeWorkload.Dataset;
import org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeWorkload.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class PageTextPrototypeResourceCorpusTest {

	@TempDir
	Path temporary;

	@Test
	void streamingLoaderDeduplicatesLabelsAndExcludesNonStringDatatypes() throws IOException {
		Path source = temporary.resolve("labels.ttl");
		Files.writeString(source, """
				@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
				<urn:subject> <urn:predicate>
				    "ALPHA beta", "gamma", "same"@en, "same"@fr, "123"^^xsd:string,
				    "", "longerword", "kappa", "delta", "10"^^xsd:integer,
				    "2026-11-09"^^xsd:date, "https://example.org"^^xsd:anyURI .
				""");
		Dataset dataset = PageTextPrototypeResourceCorpus.load(source, Order.SHUFFLED, 100);
		assertThat(dataset.labels()).containsExactlyInAnyOrder("ALPHA beta", "gamma", "same", "123", "",
				"longerword", "kappa", "delta");
		assertThat(dataset.normalized()).isEqualTo(dataset.labels()
				.stream()
				.map(label -> label.toLowerCase(Locale.ROOT))
				.toList());
		assertQueryWitnesses(dataset);
	}

	@Test
	void bundledCorpusUsesItsActualDistinctSizeAndKnownLexicalProfile() {
		Dataset dataset = PageTextPrototypeWorkload.create(Corpus.BSBM, Order.SHUFFLED, 100_000);
		assertThat(dataset.labels()).hasSize(4_766).doesNotHaveDuplicates();
		assertThat(dataset.normalized()).doesNotHaveDuplicates();
		assertThat(dataset.normalized().stream().mapToInt(String::length).sum()).isEqualTo(1_841_530);
		assertThat(dataset.normalized().stream().mapToInt(String::length).min()).hasValue(3);
		assertThat(dataset.normalized().stream().mapToInt(String::length).max()).hasValue(2_029);
		assertQueryWitnesses(dataset);
	}

	@Test
	void capAndOrderingRetainTheSameSelectedLabelsAndQueries() {
		Dataset shuffled = PageTextPrototypeWorkload.create(Corpus.BSBM, Order.SHUFFLED, 256);
		Dataset clustered = PageTextPrototypeWorkload.create(Corpus.BSBM, Order.CLUSTERED, 256);
		assertThat(shuffled.labels()).hasSize(256).doesNotHaveDuplicates();
		assertThat(clustered.labels()).containsExactlyInAnyOrderElementsOf(shuffled.labels());
		assertThat(clustered.labels())
				.isSortedAccordingTo(Comparator.comparing(label -> label.toLowerCase(Locale.ROOT)));
		assertThat(clustered.queries()).isEqualTo(shuffled.queries());
		assertQueryWitnesses(shuffled);
		assertQueryWitnesses(clustered);
	}

	private static void assertQueryWitnesses(Dataset dataset) {
		for (String name : new String[] { "contains_rare", "contains_phrase", "contains_common_word", "prefix_rare",
				"prefix_common", "equals_hit" }) {
			assertThat(dataset.normalized().stream().anyMatch(dataset.query(name)::matches)).as(name).isTrue();
		}
		for (String name : new String[] { "contains_absent_word", "contains_repeated", "prefix_miss", "equals_miss" }) {
			assertThat(dataset.normalized().stream().anyMatch(dataset.query(name)::matches)).as(name).isFalse();
		}
	}
}
